(() => {
  const el = document.querySelector('#view-plans') || document.querySelector('[id*="compare"]');
  if (el) el.scrollIntoView();
  // find toggle buttons with text Mensual/Anual
  const btns = [...document.querySelectorAll('button, [role="tab"], label, input')].filter(b => /mensual|anual|ahorro/i.test(b.textContent || b.getAttribute('aria-label') || ''));
  return btns.map(b => ({tag: b.tagName, text: (b.textContent||'').trim().slice(0,80), aria: b.getAttribute('aria-label'), pressed: b.getAttribute('aria-pressed'), checked: b.checked, cls: b.className.slice(0,80)}));
})()

(() => {
  const btns = [...document.querySelectorAll('button')].filter(b => /^Mensual$/i.test((b.textContent||'').trim()));
  const visible = btns.filter(b => b.offsetParent !== null);
  const b = visible[0] || btns[0];
  b.scrollIntoView({block:'center'});
  const r = b.getBoundingClientRect();
  return {count: btns.length, visible: visible.length, x: r.x + r.width/2, y: r.y + r.height/2, w: r.width, h: r.height, innerW: window.innerWidth, innerH: window.innerHeight};
})()

(() => {
  const btns = [...document.querySelectorAll('button')].filter(b => /^(Mensual|AHORRO DEL 15 % por año)$/i.test((b.textContent||'').trim()));
  const states = btns.map(b => ({t: b.textContent.trim(), pressed: b.getAttribute('aria-pressed'), vis: b.offsetParent!==null}));
  // Get compare module text
  const sec = document.querySelector('#view-plans') || document.body;
  const txt = sec.innerText || '';
  const i = txt.indexOf('Ciudades');
  return {states, snippet: txt.slice(Math.max(0,i-200), i+1200)};
})()

(() => {
  const out = [];
  document.querySelectorAll('select, input[type=radio], button, [role=option], [role=combobox], [role=listbox]').forEach(el => {
    const t = (el.textContent||'').trim().slice(0,60);
    if (/mensual|permanencia|meses/i.test(t) || el.tagName==='SELECT' || el.type==='radio' || /combobox|listbox/.test(el.getAttribute('role')||'')) {
      const r = el.getBoundingClientRect();
      out.push({tag: el.tagName, type: el.type, role: el.getAttribute('role'), name: el.name, value: el.value, text: t, x: r.x + r.width/2, y: r.y + r.height/2, w: r.width, h: r.height, opts: el.tagName==='SELECT' ? [...el.options].map(o=>o.text+'|'+o.value) : undefined});
    }
  });
  return {out, scrollY: window.scrollY, innerW: window.innerWidth, innerH: window.innerHeight};
})()

